python3 -B -c 'from pathlib import Path
from subprocess import CompletedProcess
from tests import codex_review_run as r
run=r.ReviewRun(head="a"*40,base="b"*40,label="probe",attempt=1,pr_url="https://github.com/thejuran/triggarr/pull/1",scope="probe",phase_dir=Path(".planning/phases/x"),trusted=False)
calls=[]
def fake(argv,**kw):
 calls.append(argv)
 if "diff" in argv and "--name-status" not in argv: return CompletedProcess(argv,0,stdout="x"*(r.MAX_INSPECTION_INPUT_BYTES+1))
 if "--name-status" in argv: return CompletedProcess(argv,0,stdout="A\0big.txt\0")
 if "ls-tree" in argv: return CompletedProcess(argv,0,stdout="100644 blob "+"c"*40+"\tbig.txt\0")
 if "cat-file" in argv: return CompletedProcess(argv,0,stdout=b"x"*(r.PER_FILE_CONTENT_LIMIT+1))
 raise AssertionError(argv)
text,stats=r.build_inspection_input(run,fake)
print(dict(stats,blob_reads_after_oversized_diff=sum("cat-file" in c for c in calls),retained_text_bytes=len(text.encode())))'

